-- ---------------------------------------------------------------------
-- TOUR (22), GUIA (14) y GUIA_IDIOMA (27)
--   'Taller de cestería en Filandia' no tiene salidas y 'Tour arqueológico quimbaya' tiene
--   salidas sin participantes: así el reporte 9 muestra los dos casos.
--   Todos los guías hablan español; algunos también inglés, francés, alemán o portugués.
-- ---------------------------------------------------------------------
INSERT INTO tour (id_tour, nombre, descripcion, duracion_horas, dificultad, edad_minima, precio_persona, id_categoria, id_prestador) VALUES
  (1, 'Caminata Valle de Cocora', 'Recorrido entre palmas de cera hasta Acaime, cruzando puentes colgantes sobre el río Quindío. Incluye hidratación y seguro.', 5.00, 'MEDIA', 8, 120000, 3, 1),
  (2, 'Cabalgata por el Valle de Cocora', 'Paseo a caballo por senderos del valle con guía baqueano y parada en mirador de palmas.', 3.00, 'MEDIA', 12, 150000, 3, 1),
  (3, 'Avistamiento de aves en Acaime', 'Observación de colibríes y aves endémicas en la reserva de Acaime, con binoculares.', 4.00, 'BAJA', 0, 95000, 3, 1),
  (4, 'Canopy y rappel en cascada', 'Circuito de canopy de cinco líneas y descenso en rappel por una cascada de 30 metros.', 3.00, 'ALTA', 12, 180000, 2, 2),
  (5, 'Torrentismo en Buenavista', 'Descenso por el cauce de una quebrada con cuerdas y equipo certificado.', 3.50, 'ALTA', 14, 160000, 2, 2),
  (6, 'Tour del café en finca tradicional', 'Del grano a la taza: recolección, beneficio, tostión y catación en una finca familiar.', 3.50, 'BAJA', 0, 85000, 4, 3),
  (7, 'Recorrido histórico por Filandia', 'Arquitectura de la colonización antioqueña, calle del Tiempo Detenido y mirador.', 2.50, 'BAJA', 0, 60000, 1, 3),
  (8, 'Taller de cestería en Filandia', 'Taller práctico con artesanos locales sobre el tejido de canastos en bejuco.', 2.00, 'BAJA', 6, 70000, 1, 3),
  (9, 'Ruta en bicicleta Salento - Boquía', 'Descenso en bicicleta todoterreno por la vía antigua hasta Boquía y regreso en jeep.', 4.00, 'MEDIA', 14, 130000, 2, 4),
  (10, 'Trekking al Paramillo del Quindío', 'Ascenso de alta montaña por el páramo, con noche previa de aclimatación no incluida.', 10.00, 'ALTA', 16, 380000, 3, 4),
  (11, 'Parapente biplaza en Buenavista', 'Vuelo biplaza sobre el valle del río Barragán con piloto certificado y video incluido.', 1.50, 'ALTA', 14, 250000, 2, 5),
  (12, 'Cata de cafés especiales', 'Cata guiada de cuatro cafés especiales de Salento con maridaje.', 2.00, 'BAJA', 0, 75000, 4, 6),
  (13, 'Del grano a la taza en Salento', 'Recorrido por cultivos, despulpado, secado y preparación de bebidas de café.', 3.00, 'BAJA', 0, 90000, 4, 6),
  (14, 'Avistamiento de aves en Génova', 'Jornada de observación en bosque andino; posibilidad de ver barranquero y tángaras.', 6.00, 'MEDIA', 10, 140000, 3, 7),
  (15, 'Armenia cultural y Museo del Oro Quimbaya', 'Recorrido por el centro, la plaza de Bolívar y el museo de la cultura quimbaya.', 3.00, 'BAJA', 0, 55000, 1, 8),
  (16, 'Ruta gastronómica de Armenia', 'Degustación de platos típicos del Quindío en plazas y restaurantes tradicionales.', 3.00, 'BAJA', 0, 98000, 1, 8),
  (17, 'Rafting en el río Barragán', 'Descenso en balsa por rápidos clase III con instructores y equipo de seguridad.', 4.00, 'ALTA', 14, 170000, 2, 9),
  (18, 'Pijao pueblo sin prisa', 'Recorrido por el primer pueblo Cittaslow de Colombia: plaza, balcones y cafés.', 3.00, 'BAJA', 0, 65000, 1, 10),
  (19, 'Caminata a la cascada de Pijao', 'Sendero de montaña hasta una cascada en la cordillera Central.', 4.00, 'MEDIA', 10, 80000, 3, 10),
  (20, 'Noche de velas en Quimbaya', 'Recorrido nocturno por los barrios decorados con faroles y velas en temporada de diciembre.', 2.00, 'BAJA', 0, 50000, 1, 11),
  (21, 'Tour arqueológico quimbaya', 'Visita a sitios con hallazgos de la cultura quimbaya y taller de réplicas en arcilla.', 3.00, 'BAJA', 8, 70000, 1, 11),
  (22, 'Paseo en Willys por fincas cafeteras', 'Recorrido en jeep Willys por fincas de Montenegro con almuerzo campesino.', 4.00, 'BAJA', 0, 110000, 4, 12);
